export const getTasks = async (args, context) => {
  return context.entities.Task.findMany({
    orderBy: { id: 'asc' }
  })
}

export const getProjectStats = async (args, context) => {
  const projects = await context.entities.Project.findMany({
    include: {
      tasks: true
    },
    orderBy: { id: 'asc' }
  })
  return projects.map(project => {
    const total = project.tasks.length
    const done = project.tasks.filter(t => t.done).length
    return {
      id: project.id,
      name: project.name,
      total,
      done
    }
  })
}

import { HttpError } from 'wasp/server'

export const addTask = async ({ projectId, title }, context) => {
  if (!title || typeof title !== 'string' || title.trim() === '') {
    throw new HttpError(400, 'Title is required')
  }
  return context.entities.Task.create({
    data: {
      title,
      projectId,
      done: false
    }
  })
}

export const toggleTask = async ({ id }, context) => {
  const task = await context.entities.Task.findUnique({
    where: { id }
  })
  if (!task) {
    throw new HttpError(404, `Task with id ${id} not found`)
  }
  return context.entities.Task.update({
    where: { id },
    data: {
      done: !task.done
    }
  })
}

export const devSeed = async (prisma) => {
  // Clear existing data
  await prisma.task.deleteMany()
  await prisma.project.deleteMany()

  // Create Work project and its tasks
  await prisma.project.create({
    data: {
      name: 'Work',
      tasks: {
        create: [
          { title: 'Ship release', done: true },
          { title: 'Write docs', done: false }
        ]
      }
    }
  })

  // Create Home project and its tasks
  await prisma.project.create({
    data: {
      name: 'Home',
      tasks: {
        create: [
          { title: 'Buy groceries', done: false }
        ]
      }
    }
  })

  console.log('Database seeded successfully!')
}
